// js
const employment = ctx.subject.employment;
const terms = employment.terms;
const extension = get(employment, 'employee_extension_data', {});
const facts = get(extension, 'facts', {});
const signed = get(employment, 'signed_contract_period', null);
const probation = get(terms, 'probation_period', null);
const ended = get(employment.effective_range, 'to', null);
if (ended != null && ended < ctx.run.salary_coverage.from) return false;
if (['CONTRACTOR', 'CONSULTANT', 'PAYEE', 'INTERN', 'APPRENTICE'].includes(employment.engagement))
	return false;
if (probation != null && ctx.run.salary_coverage.from <= probation.to) return false;
if (get(facts, 'domestic_worker', false) === true) return false;
if (get(extension, 'term_facts.receiving_pension', false) === true) return false;
if (get(extension, 'term_facts.pass_type', '') === 'INTRA_COMPANY_TRANSFER') return false;

if (get(facts, 'statutory.SI.elections.si_treaty_exempt', false) === true) return false;
const review = get(extension, 'term_facts.insurance_review', null);
if (
	get(review, 'month', '') === String(ctx.as_of).substring(0, 7) &&
	get(review, 'si_temporarily_suspended', false) === true
)
	return false;

const foreign = !['VN', 'VNM', 'VIETNAM', 'VIETNAMESE', 'Vietnam', 'Vietnamese'].includes(
	String(get(facts, 'nationality', 'VN'))
);
const months =
	signed?.from == null || signed.to == null
		? Infinity
		: calendar_completed_months(signed.from, add_days(signed.to, 1));
if (
	months <
	(foreign ? ctx.lookup.foreign_minimum_contract_months : ctx.lookup.minimum_contract_months)
)
	return false;
const pay = Number(get(ctx.subtotals, 'BASIC', 0));
return employment.engagement !== 'PART_TIME' || pay >= ctx.lookup.floor;

